CREATE TABLE activations(id TEXT PRIMARY KEY, email TEXT NOT NULL, token_hash TEXT NOT NULL UNIQUE, active INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE orders(id TEXT PRIMARY KEY, activation_id TEXT NOT NULL REFERENCES activations(id), amount_cents INTEGER NOT NULL DEFAULT 19900, paid INTEGER NOT NULL DEFAULT 0, pf_payment_id TEXT UNIQUE);
CREATE TABLE content(id TEXT PRIMARY KEY, title TEXT NOT NULL, category TEXT NOT NULL, url TEXT, object_key TEXT, published INTEGER NOT NULL DEFAULT 1, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE uploads(id TEXT PRIMARY KEY, object_key TEXT NOT NULL, owner TEXT NOT NULL, title TEXT NOT NULL, category TEXT NOT NULL, content_type TEXT NOT NULL, size INTEGER NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
